#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void layer_norm_kernel(
    const half* __restrict__ input,
    half* __restrict__ output,
    const half* __restrict__ weight,
    const half* __restrict__ bias,
    const float* __restrict__ mean,
    const float* __restrict__ rstd,
    int batch_size,
    int features,
    int dim1,
    int dim2
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * features * dim1 * dim2;

    if (idx >= total_elements) return;

    // Calculate which batch, feature, and spatial indices this thread handles
    int spatial_idx = idx % (dim1 * dim2);
    int dim2_idx = spatial_idx % dim2;
    int dim1_idx = spatial_idx / dim2;
    int feat_idx = (idx / (dim1 * dim2)) % features;
    int batch_idx = idx / (features * dim1 * dim2);

    // Get the mean and rstd for this feature dimension
    float cur_mean = mean[feat_idx];
    float cur_rstd = rstd[feat_idx];

    // Get the weight and bias for this feature
    float w = __half2float(weight[feat_idx]);
    float b = __half2float(bias[feat_idx]);

    // Get input value
    float x = __half2float(input[idx]);

    // Apply layer normalization: (x - mean) * rstd * weight + bias
    float normalized = (x - cur_mean) * cur_rstd;
    float result = normalized * w + b;

    output[idx] = __float2half(result);
}

// Helper function to compute mean and rstd for each feature dimension
__global__ void compute_stats_kernel(
    const half* __restrict__ input,
    float* __restrict__ mean,
    float* __restrict__ rstd,
    int batch_size,
    int features,
    int dim1,
    int dim2
) {
    int feat_idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (feat_idx >= features) return;

    // Compute mean and variance for this feature across all batches and spatial dimensions
    double sum = 0.0;
    double sum_sq = 0.0;
    int count = batch_size * dim1 * dim2;

    for (int batch = 0; batch < batch_size; ++batch) {
        for (int d1 = 0; d1 < dim1; ++d1) {
            for (int d2 = 0; d2 < dim2; ++d2) {
                int idx = batch * (features * dim1 * dim2) + feat_idx * (dim1 * dim2) + d1 * dim2 + d2;
                float val = __half2float(input[idx]);
                sum += val;
                sum_sq += val * val;
            }
        }
    }

    float mean_val = static_cast<float>(sum / count);
    float var = static_cast<float>(sum_sq / count - mean_val * mean_val);
    float std = sqrtf(var + 1e-5f);  // Add epsilon for numerical stability

    mean[feat_idx] = mean_val;
    rstd[feat_idx] = 1.0f / std;
}
"""

