        grid_size = (total_elements + block_size - 1) // block_size

        module.layer_norm_kernel(
            input_flat.data_ptr(),
            output.data_ptr(),
            self.weight.data_ptr(),
            self.bias.data_ptr(),
            mean.data_ptr(),
            rstd.data_ptr(),
            batch_size,
            features,
            dim1,
            dim2,
